create database customer_behavior;

USE customer_behavior;

select * from customer_shopping;

#Q1 what is the total revenue generated by male and female customers? 
SELECT
gender,
sum(purchase_amount)  
FROM customer_shopping AS revenue
group by gender ;

#Q2 which customer used a discount code but still paid more than the average purchase amount? 
select customer_id,purchase_amount
from customer_shopping
where discount_applied='yes' AND purchase_amount > (select avg(purchase_amount) from customer_shopping );

#Q3 what are the top 5 product with the highest average review rating
select item_purchased,Round(AVG(review_rating),2)
from customer_shopping
group by item_purchased
order by Round(AVG(review_rating),2)  desc
limit 5; 

#Q4 Compare the average purchase amount between standard and express  shipping 

select shipping_type,
AVG(purchase_amount) as Average_purchase
from customer_shopping
where shipping_type IN ('Standard','Express')
group by shipping_type;

#Q5 Do subcribed customer spend more? compare average spend and total revenue between subcribers and non-subcribers

select subscription_status,
count(customer_id) as customer_count,
AVG(purchase_amount) as Average_purchase,
sum(purchase_amount) as Total_purchase
from customer_shopping
group by subscription_status;

# Q6 which top 5 products have the highest percentage of purchasing with discount applied

select item_purchased,
ROUND(100*sum(case
when discount_applied = 'Yes' THEN 1 ELSE 0 END)/count(*),2) AS discount_rate
from customer_shopping
group by item_purchased
order by discount_rate desc
limit 5 ;

#Q7 segemnt ccustomer into NEW.RETURNING AND LOYAL based on their total number of previous and show the count  of each segment 
with customer_type AS  (
select customer_id,previous_purchases,
CASE  
    WHEN previous_purchases = 1 THEN 'NEW'  
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'RETURNING'
    ELSE "LOYAL"
END  AS customer_segment 
FROM customer_shopping
)
SELECT 
    customer_segment,count(*) AS "number of customer"
from customer_type
group by customer_segment;

#Q8 What are the top 3 most purchased products within each category

WITH item_counts AS (
select category,
item_purchased,
count(customer_id) as total_count,
row_number() over (partition by category order by count(customer_id) desc) AS item_rank  
from customer_shopping
group by category,item_purchased
)
select item_rank,item_purchased,category,total_count
from item_counts
where item_rank <= 3 ;

#Q9 are customer who are repeated buyer (more than 5 previous purchased) also likely to subscribed

select subscription_status,
count(customer_id)
from customer_shopping
where previous_purchases>=5
group by subscription_status;
    
#Q10 what is the revenue contribution of each age_agroup

select age_group,
sum(purchase_amount) AS revenue 
from customer_shopping
group by age_group;

